"""Scripted test-only inference responses; nothing here is generated by a model."""

# ruff: noqa: E501

import json
from collections.abc import Iterator, Sequence
from contextlib import contextmanager
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from threading import Thread

MOCK_NOTIONAL_DIFF = """diff --git a/src/exchange_demo/orders.py b/src/exchange_demo/orders.py
--- a/src/exchange_demo/orders.py
+++ b/src/exchange_demo/orders.py
@@ -16,4 +16,4 @@ def validate_order(order: Order) -> None:
     if order.quantity <= 0:
         raise ValueError("Quantity must be positive")
-    if order.price * order.quantity >= MAX_ORDER_NOTIONAL:
+    if order.price * order.quantity > MAX_ORDER_NOTIONAL:
         raise ValueError("Order notional exceeds the maximum")
diff --git a/tests/test_orders.py b/tests/test_orders.py
--- a/tests/test_orders.py
+++ b/tests/test_orders.py
@@ -7,6 +7,5 @@ class OrderValidationTest(unittest.TestCase):
     def test_valid_order_is_accepted(self) -> None:
         validate_order(Order("a", price=100, quantity=10))

-    @unittest.expectedFailure
     def test_notional_boundary_is_accepted(self) -> None:
         validate_order(Order("boundary", price=10_000, quantity=100))
"""


@contextmanager
def fake_inference_endpoint(
    responses: Sequence[str],
) -> Iterator[tuple[str, list[dict[str, object]]]]:
    scripted_responses = iter(responses)
    requests: list[dict[str, object]] = []

    class Handler(BaseHTTPRequestHandler):
        def do_POST(self) -> None:
            payload = json.loads(self.rfile.read(int(self.headers["Content-Length"])))
            requests.append({"path": self.path, **payload})
            content = next(scripted_responses)
            body = json.dumps(
                {
                    "choices": [
                        {
                            "finish_reason": "stop",
                            "message": {"role": "assistant", "content": content},
                        }
                    ],
                    "usage": {"prompt_tokens": 10, "completion_tokens": 5},
                }
            ).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, format: str, *args: object) -> None:
            return

    server = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
    thread = Thread(target=server.serve_forever, daemon=True)
    thread.start()
    try:
        yield f"http://127.0.0.1:{server.server_port}/v1", requests
    finally:
        server.shutdown()
        thread.join(timeout=2)
        server.server_close()
